let csrf="";const message=document.querySelector("#message");async function request(path,options={}){options.headers={"Content-Type":"application/json",...(options.headers||{})};const response=await fetch(path,options);const body=[202,204].includes(response.status)?{}:await response.json();if(!response.ok)throw new Error(body.error||"Request failed");return body}function formJSON(form){return Object.fromEntries(new FormData(form))}async function updatePost(post,changes){await request(`/api/v1/posts/${post.id}`,{method:"PUT",headers:{"X-Watchpost-CSRF":csrf,"If-Match":String(post.version)},body:JSON.stringify({...post,...changes})});await loadPosts()}async function loadPosts(){const body=await request("/api/v1/posts");const list=document.querySelector("#posts");list.replaceChildren(...body.posts.map(post=>{const card=document.createElement("article");card.className="post";const title=document.createElement("h3");title.textContent=post.name;const kind=document.createElement("small");kind.textContent=post.kind;const id=document.createElement("p");id.textContent=post.id;const maintenance=document.createElement("button");maintenance.textContent=post.maintenance?"End maintenance":"Start maintenance";maintenance.onclick=()=>updatePost(post,{maintenance:!post.maintenance});const archive=document.createElement("button");archive.textContent=post.archived?"Restore":"Archive";archive.onclick=()=>updatePost(post,{archived:!post.archived});card.append(title,kind,id,maintenance,archive);return card}));document.querySelector("#inventory").hidden=false}document.querySelector("#setup").addEventListener("submit",async event=>{event.preventDefault();try{await request("/api/v1/setup",{method:"POST",body:JSON.stringify(formJSON(event.currentTarget))});message.textContent="Administrator created. Sign in."}catch(error){message.textContent=error.message}});document.querySelector("#login").addEventListener("submit",async event=>{event.preventDefault();try{const body=await request("/api/v1/login",{method:"POST",body:JSON.stringify(formJSON(event.currentTarget))});csrf=body.csrf_token;document.querySelector("#create").hidden=false;await loadPosts();message.textContent=`Signed in as ${body.user.email}`}catch(error){message.textContent=error.message}});document.querySelector("#create").addEventListener("submit",async event=>{event.preventDefault();const post=formJSON(event.currentTarget);post.labels={};try{await request("/api/v1/posts",{method:"POST",headers:{"X-Watchpost-CSRF":csrf},body:JSON.stringify(post)});event.currentTarget.reset();await loadPosts();message.textContent="Post created."}catch(error){message.textContent=error.message}});
